def find_path(graph, start, goal):
    # A helper function to check if a node has been visited
    def is_visited(visited, node):
        return node in visited

    # A helper function for the recursive path search
    def search(visited, current_node, path):
        visited.add(current_node)
        path.append(current_node)
        if current_node == goal:
            return path
        for neighbor in graph.get(current_node, []):
            if not is_visited(visited, neighbor):
                result = search(visited.copy(), neighbor, path.copy())
                if result:
                    return result
        path.pop()
        return None

    path = search(set(), start, [])
    return path if path else None
