def find_path(graph, start, goal):
    if start not in graph or goal not in graph:
        return None

    # Dictionary to keep track of parent nodes (to reconstruct the path)
    parent = {node: None for node in graph}
    # Dictionary to keep track of visited nodes to avoid cycles
    visited = set()

    # Queue for BFS
    queue = [(start, [start])]

    while queue:
        current, path = queue.pop(0)
        if current not in visited:
            visited.add(current)
            if current == goal:
                return path

            # Explore neighbours
            for neighbor in graph[current]:
                if neighbor not in visited:
                    parent[neighbor] = current
                    queue.append((neighbor, path + [neighbor]))

    # If we reach here, goal is unreachable
    return None
